import csv
import io


def parse_csv(raw_csv: str):
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    stream = io.StringIO(raw_csv, newline="")
    # Skip the leading comment preamble before parsing any CSV records.
    while True:
        start = stream.tell()
        line = stream.readline()
        if not line:
            return {"columns": [], "rows": []}
        if line.strip() and not line.lstrip().startswith("#"):
            stream.seek(start)
            break

    reader = csv.reader(stream, delimiter=",", quotechar='"', doublequote=True)
    columns = next(reader)
    rows = list(reader)

    # Keep overflow fields in extra columns rather than dropping or merging them.
    width = max(5, len(columns), max((len(row) for row in rows), default=0))
    used_names = set(columns)
    suffix = 1
    while len(columns) < width:
        name = f"extra_{suffix}"
        suffix += 1
        if name not in used_names:
            columns.append(name)
            used_names.add(name)

    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": columns, "rows": rows}
